// === Tab: sketch.js ===

// In the style of Anni Albers (1899-1994).
// References: https://en.wikipedia.org/wiki/Maze_generation_algorithm

import { mountFlex } from "https://cdn.jsdelivr.net/npm/p5.flex@0.1.1/src/p5.flex.min.mjs"
/* [Inlined Multi-Tab] Grid.js */
/* [Inlined Multi-Tab] shader.js */

mountFlex(p5)
mountGrid(p5)

new p5((p) => {
	const [WIDTH, HEIGHT] = [600, 600]
	const PIXEL_DENSITY = 2
	const CANVAS_SIZE = [WIDTH, HEIGHT]
	const TEXEL_SIZE = [1 / (WIDTH * PIXEL_DENSITY), 1 / (HEIGHT * PIXEL_DENSITY)]
	const color = p.random([
		[1, 1, 0],
		[0, 0.8, 1],
		[1, 0.3, 0.3],
		[1, 0.5, 0],
	])

	const [cols, rows] = [15, 15]
	const stack = []

	let cnv, gfx, theShader, gs, curr

	p.setup = () => {
		p.createCanvas(WIDTH, HEIGHT)
		p.flex({ container: { padding: "20px" } })

		p.pixelDensity(PIXEL_DENSITY)

		cnv = p.createGraphics(WIDTH, HEIGHT)
		gfx = p.createGraphics(WIDTH, HEIGHT, p.WEBGL)
		theShader = p.createShader(vert, frag)

		p.noStroke()
		cnv.noStroke()

		gs = cnv.Grid({ cols, rows, order: p.LRTB })

		const calcID = (col, row) => {
			if (col < 0 || row < 0 || col >= gs.cols || row >= gs.rows) return -1
			return col + row * gs.cols
		}

		for (let cell of gs.cells) {
			cell.visited = false
			cell.walls = [true, true, true, true]
			cell.neighbors = []
			cell.chooseNeighbor = () => p.random(cell.neighbors)
			cell.hasUnvisitedNeighbors = () => {
				cell.neighbors = []
				const t = gs.cells[calcID(cell.col, cell.row - 1)]
				const r = gs.cells[calcID(cell.col + 1, cell.row)]
				const b = gs.cells[calcID(cell.col, cell.row + 1)]
				const l = gs.cells[calcID(cell.col - 1, cell.row)]
				if (t && !t.visited) cell.neighbors.push(t)
				if (r && !r.visited) cell.neighbors.push(r)
				if (b && !b.visited) cell.neighbors.push(b)
				if (l && !l.visited) cell.neighbors.push(l)
				return cell.neighbors.length > 0
			}
		}

		curr = gs.cells[p.floor(p.random(cols * rows))]
		curr.visited = true
		stack.push(curr)
	}

	p.draw = () => {
		p.background(255)
		cnv.background(255)
		gfx.background(255)

		gs.generate(content)
		if (stack.length) {
			curr = stack.pop()
			if (curr.hasUnvisitedNeighbors()) {
				stack.push(curr)
				const next = curr.chooseNeighbor()
				removeWalls(curr, next)
				next.visited = true
				stack.push(next)
			}
		}

		gfx.shader(theShader)
		theShader.setUniform("tex0", cnv)
		theShader.setUniform("canvasSize", CANVAS_SIZE)
		theShader.setUniform("texelSize", TEXEL_SIZE)
		theShader.setUniform("color", color)
		gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1)

		p.image(gfx, 0, 0)
	}

	const content = (cell) => {
		cnv.stroke(0)
		cnv.strokeCap(cnv.PROJECT)
		cnv.strokeWeight(cell.w / 2)
		const visited = cell.visited
		const walls = cell.walls
		if (walls[0]) cnv.line(0, 0, cell.w, 0)
		if (walls[1]) cnv.line(cell.w, 0, cell.w, cell.h)
		if (walls[2]) cnv.line(0, cell.h, cell.w, cell.h)
		if (walls[3]) cnv.line(0, 0, 0, cell.h)
		if (!visited) {
			cnv.translate(cell.w / 2, cell.h / 2)
			cnv.rectMode(cnv.CENTER)
			cnv.fill(0)
			cnv.noStroke()
			cnv.square(0, 0, cell.w)
		}
	}

	const removeWalls = (curr, next) => {
		const hor = curr.col - next.col
		if (hor === +1) [curr.walls[3], next.walls[1]] = [false, false]
		if (hor === -1) [curr.walls[1], next.walls[3]] = [false, false]
		const ver = curr.row - next.row
		if (ver === +1) [curr.walls[0], next.walls[2]] = [false, false]
		if (ver === -1) [curr.walls[2], next.walls[0]] = [false, false]
	}
})



// === Tab: shader.js ===

// noprotect

// https://github.com/ZRNOF/Shox
import * as Shox from "https://cdn.jsdelivr.net/npm/shox@1.0.0/src/Shox.js"

const frag = `#version 300 es
  precision mediump float;

  uniform sampler2D tex0;
  uniform vec2 texelSize;
  uniform vec2 canvasSize;
  uniform vec3 color;

  ${Shox.flip}
  ${Shox.noiseMath}
  ${Shox.snoise3D}
  ${Shox.snoise3DImage}

  float Rectangle(vec2 uv, vec2 pos, vec2 size) {
    uv -= pos;
    vec2 d = abs(uv)-size/2.;
    return smoothstep(.0001, .0, max(d.x, d.y));
  }

  vec4 OVER(vec4 base, vec4 blend) {
    return (1. - blend.a) * base + blend.a * blend;
  }

  in vec2 vTexCoord;
  out vec4 fragColor;
  void main() {
    vec2 uv = vTexCoord;
    vec2 ouv = uv;
    uv = (uv-.5)*1.2+.5;

    vec4 ori = texture(tex0, uv);
    ori.a *= mix(0., 1., ori.r);
    ori.rgb *= color;

    vec2 ruv = flipX(flipY(uv - .02));
    vec4 flp = texture(tex0, ruv);
    flp.rgb = 1.-flp.rgb*.07;

    float rect = Rectangle(ouv, vec2(.5), vec2(.84));
    vec4 RECT = vec4(.9, .9, .85, 1.) * rect;

    float bg = Rectangle(ouv, vec2(.5), vec2(1.));
    vec4 BG = vec4(vec3(.95), 1.) * bg;

    float noise = 1.;
    noise *= 1.-.02*snoise3DImage(ouv*vec2(.05, 1.), 200., 1.5, .5, vec3(0.)).r;
    noise *= 1.-.02*snoise3DImage(ouv*vec2(1., .05), 200., 1.5, .5, vec3(0.)).r;
    noise *= 1.-.02*snoise3DImage(ouv*vec2(1.,  1.),  10., 1.5, .5, vec3(0.)).r;

    vec4 color = OVER(OVER(BG, RECT), ori);
    color *= flp;
    color.rgb *= noise;

    fragColor = color;
  }
`

const vert = `#version 300 es

  in vec4 aPosition;
  in vec2 aTexCoord;

  out vec2 vTexCoord;

  void main() {
    vTexCoord = aTexCoord;
    gl_Position = aPosition;
  }
`



